package org.pms.silverocean.database.pms;
import org.pms.silverocean.database.pms.entities.AffiliateProfile;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Lock;import org.springframework.data.jpa.repository.Query;import jakarta.persistence.LockModeType;import java.util.Optional;
public interface AffiliateProfileRepo extends JpaRepository<AffiliateProfile,Long>{Optional<AffiliateProfile> findByUserIdAndActiveTrue(long userId);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("SELECT p FROM AffiliateProfile p WHERE p.userId=:userId AND p.active=true")Optional<AffiliateProfile> findForUpdateByUserId(long userId);Optional<AffiliateProfile> findByReferralCodeAndActiveTrue(String code);boolean existsByReferralCode(String code);}
